  1108→    /// Builds a [`EthTransactionValidator`] and spawns validation tasks via the
  1109→    /// [`TransactionValidationTaskExecutor`]
  1110→    ///
  1111→    /// The validator will spawn `additional_tasks` additional tasks for validation.
  1112→    ///
  1113→    /// By default this will spawn 1 additional task.
  1114→    pub fn build_with_tasks<Tx, T, S>(
  1115→        self,
  1116→        tasks: T,
  1117→        blob_store: S,
  1118→    ) -> TransactionValidationTaskExecutor<EthTransactionValidator<Client, Tx>>
  1119→    where
  1120→        T: TaskSpawner,
  1121→        S: BlobStore,
  1122→    {
  1123→        let additional_tasks = self.additional_tasks;
  1124→        let validator = self.build(blob_store);
  1125→
  1126→        let (tx, task) = ValidationTask::new();
  1127→
  1128→        // Spawn validation tasks, they are blocking because they perform db lookups
  1129→        for _ in 0..additional_tasks {
  1130→            let task = task.clone();
  1131→            tasks.spawn_blocking(Box::pin(async move {
  1132→                task.run().await;
  1133→            }));
  1134→        }
  1135→
  1136→        // we spawn them on critical tasks because validation, especially for EIP-4844 can be quite
  1137→        // heavy
  1138→        tasks.spawn_critical_blocking(
  1139→            "transaction-validation-service",
  1140→            Box::pin(async move {
  1141→                task.run().await;
  1142→            }),
  1143→        );
  1144→
  1145→        let to_validation_task = Arc::new(Mutex::new(tx));
  1146→
  1147→        TransactionValidationTaskExecutor { validator: Arc::new(validator), to_validation_task }
  1148→    }
  1149→}
